package org.eink.inkprobe.notebook;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;

/** Exercise the production microphone permission policy with explicit OS and UI fakes. */
public final class NotebookBrowserMediaTest {
    private static String code(String name) throws Exception {
        String source = new String(Files.readAllBytes(Paths.get("app/src/main/java/org/eink/inkprobe/notebook/" + name + ".java")), StandardCharsets.UTF_8);
        return source.substring(source.indexOf("/**")).replace("final class " + name, "static final class " + name);
    }
    public static void main(String[] args) throws Exception {
        String fixture = String.join("\n",
            "package org.eink.inkprobe.notebook;import java.util.*;import java.util.function.*;public class BrowserMediaFixture {",
            "static class Manifest {static class permission {static final String RECORD_AUDIO=\"android.permission.RECORD_AUDIO\";}}static class PackageManager {static final int PERMISSION_GRANTED=0;}",
            "static class Activity {static final int MODE_PRIVATE=0;boolean granted;int requests;final Map<String,Pref> stores=new HashMap<>();int checkSelfPermission(String s){return granted?0:-1;}Pref getSharedPreferences(String n,int m){return stores.computeIfAbsent(n,k->new Pref());}void requestPermissions(String[] p,int code){check(p.length==1&&p[0].equals(Manifest.permission.RECORD_AUDIO)&&code==NotebookMicrophone.REQUEST,\"only microphone is requested\");requests++;}}static class Pref {final Map<String,Object> data=new HashMap<>();boolean getBoolean(String k,boolean d){return (Boolean)data.getOrDefault(k,d);}int getInt(String k,int d){return (Integer)data.getOrDefault(k,d);}Map<String,Object> getAll(){return new HashMap<>(data);}Editor edit(){return new Editor();}class Editor{Editor putBoolean(String k,boolean v){data.put(k,v);return this;}Editor putInt(String k,int v){data.put(k,v);return this;}Editor remove(String k){data.remove(k);return this;}void apply(){}}}",
            "interface Click{void click(Object d,int w);}static class AlertDialog {boolean showing;String message;Click positive,negative;Consumer<Object> dismiss;static class Builder {final AlertDialog dialog=new AlertDialog();Builder(Activity a){}Builder setTitle(String t){return this;}Builder setMessage(String m){dialog.message=m;return this;}Builder setNegativeButton(String s,Click c){dialog.negative=c;return this;}Builder setPositiveButton(String s,Click c){dialog.positive=c;return this;}AlertDialog create(){return dialog;}}void setOnDismissListener(Consumer<Object> c){dismiss=c;}void dismiss(){if(showing){showing=false;dismiss.accept(this);}}void accept(){if(showing){positive.click(this,1);dismiss();}}void deny(){if(showing){negative.click(this,0);dismiss();}}}static class NotebookUi {static AlertDialog shown;static void show(AlertDialog d){shown=d;d.showing=true;}}",
            "static class GeckoResult<T>{T value;static <T> GeckoResult<T> fromValue(T v){GeckoResult<T> r=new GeckoResult<>();r.value=v;return r;}}static class GeckoSession {interface PermissionDelegate {int PERMISSION_AUTOPLAY_AUDIBLE=5;interface Callback{void grant();void reject();}interface MediaCallback{void grant(MediaSource video,MediaSource audio);void reject();}class MediaSource {static final int TYPE_AUDIO=1,SOURCE_MICROPHONE=2;int type=TYPE_AUDIO,source=SOURCE_MICROPHONE;}class ContentPermission {static final int VALUE_ALLOW=1,VALUE_DENY=2;String uri;int permission=5;ContentPermission(String u){uri=u;}}default void onAndroidPermissionsRequest(GeckoSession s,String[] p,Callback c){}default void onMediaPermissionRequest(GeckoSession s,String u,MediaSource[] v,MediaSource[] a,MediaCallback c){}default GeckoResult<Integer> onContentPermissionRequest(GeckoSession s,ContentPermission p){return null;}}}",
            code("NotebookMicrophone"), code("NotebookWebsitePermissions").replace("android.content.SharedPreferences.Editor", "Pref.Editor"), code("NotebookBrowserMedia"),
            "static class Result implements GeckoSession.PermissionDelegate.Callback,GeckoSession.PermissionDelegate.MediaCallback {int grants,rejects;public void grant(){grants++;}public void grant(GeckoSession.PermissionDelegate.MediaSource video,GeckoSession.PermissionDelegate.MediaSource audio){check(video==null&&audio!=null,\"audio-only source selected\");grants++;}public void reject(){rejects++;}}static final GeckoSession.PermissionDelegate.MediaSource[] AUDIO={new GeckoSession.PermissionDelegate.MediaSource()};static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}static void request(NotebookBrowserMedia m,String uri,Result r){m.onMediaPermissionRequest(null,uri,null,AUDIO,r);}",
            "public static void run(){Activity a=new Activity();NotebookMicrophone mic=new NotebookMicrophone(a);mic.askOnce();check(a.requests==0,\"proactive Android permission waits for resume\");mic.resumed(true);check(a.requests==1,\"Android microphone requested once\");mic.resumed(false);a.granted=true;mic.permissionResult(NotebookMicrophone.REQUEST);mic.resumed(true);mic.askOnce();check(a.requests==1,\"resolved Android request is not repeated\");",
            "boolean[] foreground={true};String[] address={\"https://example.org/chat\"};String origin=\"https://example.org\";NotebookBrowserMedia media=new NotebookBrowserMedia(a,mic,()->foreground[0],()->address[0]);Result first=new Result();request(media,address[0],first);check(first.grants==0&&first.rejects==0&&NotebookUi.shown.message.startsWith(origin+\" wants\"),\"site asks for explicit consent\");NotebookUi.shown.accept();check(first.grants==1&&NotebookWebsitePermissions.get(a,origin)==NotebookWebsitePermissions.ALLOW,\"allow stores the exact origin\");Result repeat=new Result();request(media,address[0],repeat);check(repeat.grants==1,\"same page does not ask again\");media.reset();NotebookBrowserMedia reopened=new NotebookBrowserMedia(a,mic,()->foreground[0],()->address[0]);Result later=new Result();request(reopened,address[0],later);check(later.grants==1,\"allow survives navigation and a new browser session\");check(reopened.onContentPermissionRequest(null,new GeckoSession.PermissionDelegate.ContentPermission(address[0])).value==1,\"approved voice playback follows current consent\");",
            "NotebookWebsitePermissions.set(a,origin,NotebookWebsitePermissions.BLOCK);Result blocked=new Result();request(reopened,address[0],blocked);check(blocked.rejects==1&&blocked.grants==0,\"settings block takes effect on the next request\");check(reopened.onContentPermissionRequest(null,new GeckoSession.PermissionDelegate.ContentPermission(address[0])).value==2,\"block also revokes approved playback\");check(NotebookWebsitePermissions.origins(a).equals(Arrays.asList(origin)),\"settings lists the remembered origin\");NotebookWebsitePermissions.set(a,origin,NotebookWebsitePermissions.ASK);check(NotebookWebsitePermissions.origins(a).isEmpty(),\"ask-next-time removes the saved decision\");Result denied=new Result();request(reopened,address[0],denied);NotebookUi.shown.deny();check(denied.rejects==1&&NotebookWebsitePermissions.get(a,origin)==NotebookWebsitePermissions.BLOCK,\"explicit denial is remembered and can be changed later\");",
            "Result cross=new Result();request(reopened,\"https://other.example/chat\",cross);check(cross.rejects==1,\"cross-origin frame cannot inherit permission\");Result video=new Result();reopened.onMediaPermissionRequest(null,address[0],AUDIO,AUDIO,video);check(video.rejects==1,\"camera requests stay denied\");foreground[0]=false;Result hidden=new Result();request(reopened,address[0],hidden);check(hidden.rejects==1,\"background page cannot request capture\");foreground[0]=true;NotebookWebsitePermissions.set(a,origin,NotebookWebsitePermissions.ASK);",
            "Result navigation=new Result();request(reopened,address[0],navigation);AlertDialog old=NotebookUi.shown;reopened.reset();old.accept();check(navigation.rejects==1&&navigation.grants==0&&NotebookWebsitePermissions.get(a,origin)==NotebookWebsitePermissions.ASK,\"navigation cancels a stale prompt without remembering a decision\");Result changed=new Result();request(reopened,address[0],changed);address[0]=\"https://other.example/\";NotebookUi.shown.accept();check(changed.rejects==1&&NotebookWebsitePermissions.get(a,origin)==NotebookWebsitePermissions.ASK,\"origin is rechecked on consent\");address[0]=\"https://example.org/chat\";",
            "a.granted=false;Result bad=new Result();reopened.onAndroidPermissionsRequest(null,new String[]{\"android.permission.CAMERA\"},bad);check(bad.rejects==1&&a.requests==1,\"engine cannot request unrelated Android permissions\");Result runtime=new Result();request(reopened,address[0],runtime);check(a.requests==2&&runtime.grants==0&&runtime.rejects==0,\"Android permission precedes origin consent\");mic.resumed(false);a.granted=true;mic.permissionResult(NotebookMicrophone.REQUEST);reopened.reset();mic.resumed(true);check(runtime.rejects==1&&runtime.grants==0,\"replaced document cannot inherit delayed Android permission\");",
            "check(NotebookBrowserAddress.origin(\"HTTPS://EXAMPLE.org:443/path?q=one#x\").equals(origin),\"default HTTPS port shares origin\");check(NotebookBrowserAddress.origin(\"https://example.org:8443/path\").equals(\"https://example.org:8443\"),\"nondefault port remains separate\");for(String unsafe:new String[]{\"file:///page.html\",\"https://user:secret@example.org/\",\"javascript:alert(1)\"})check(NotebookBrowserAddress.origin(unsafe).isEmpty(),\"unsafe origins remain invalid\");address[0]=\"http://example.org/chat\";Result insecure=new Result();request(reopened,address[0],insecure);check(insecure.rejects==1&&insecure.grants==0,\"HTTP is never granted microphone access\");System.out.println(\"NotebookBrowserMedia: \"+checks+\" checks passed (persistent exact-origin consent, settings, Android permission and lifecycle).\");}}"
        );
        NotebookWorkspaceActivationTest.runFixture("org.eink.inkprobe.notebook.BrowserMediaFixture", fixture);
    }
}
